#!/usr/bin/env node
// Generates each client's schema and color code from shared/schema.json and
// shared/tokens.json. Run from anywhere: `npm run codegen` (writes files) or
// `npm run codegen:check` (exits 1 if a generated file is out of date).
// See shared/CONTRACTS.md.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const shared = dirname(fileURLToPath(import.meta.url))
const root = dirname(shared)
const check = process.argv.includes('--check')

const schema = JSON.parse(readFileSync(join(shared, 'schema.json'), 'utf8'))
const tokens = JSON.parse(readFileSync(join(shared, 'tokens.json'), 'utf8'))

// ── Validation ──────────────────────────────────────────────────────────────

const tables = Object.entries(schema.tables)
for (const [table, columns] of tables) {
  for (const c of columns) {
    if (!/^[a-z_]+$/.test(c.name)) throw new Error(`${table}: bad column name ${c.name}`)
    if (!['text', 'integer'].includes(c.type)) throw new Error(`${table}.${c.name}: type must be text or integer`)
    if (c.encoding === 'json' && c.type !== 'text') throw new Error(`${table}.${c.name}: json columns are text`)
    if (c.encoding === 'boolean' && c.type !== 'integer') throw new Error(`${table}.${c.name}: boolean columns are integer`)
    if (c.encoding && !['json', 'boolean'].includes(c.encoding)) throw new Error(`${table}.${c.name}: unknown encoding`)
  }
}
// Material 3 roles, then the app's blocking-state roles (blocked, unlocked, pending).
const colors = Object.entries(tokens.color)
const blockingColors = Object.entries(tokens.blocking)
for (const [role, { light, dark }] of [...colors, ...blockingColors]) {
  for (const hex of [light, dark]) if (!/^#[0-9A-F]{6}$/.test(hex)) throw new Error(`${role}: colors are #RRGGBB, got ${hex}`)
}

const columnsWith = (encoding) =>
  tables
    .map(([table, columns]) => [table, columns.filter((c) => c.encoding === encoding).map((c) => c.name)])
    .filter(([, names]) => names.length > 0)

const header = (comment, source) =>
  `${comment} Generated by shared/codegen.mjs from shared/${source}. Do not edit: change\n` +
  `${comment} the source and run \`npm run codegen\`.\n`

/** The column's trailing comment: its encoding and note, if any. */
const columnComment = (c) => [c.encoding, c.note].filter(Boolean).join(' — ')

const kebab = (role) => role.replace(/[A-Z]/g, (ch) => `-${ch.toLowerCase()}`)

// ── Android ─────────────────────────────────────────────────────────────────

const kotlinSchema = `${header('//', 'schema.json')}
package dev.brainfence.data.db

import com.powersync.db.schema.Column
import com.powersync.db.schema.Schema
import com.powersync.db.schema.Table

/**
 * PowerSync local SQLite schema — mirrors the Supabase Postgres tables.
 *
 *  - \`id\` is implicit (managed by PowerSync, not declared)
 *  - JSONB / arrays → Column.text (stored as JSON strings), listed in [JSON_ENCODED_COLUMNS]
 *  - BOOLEAN        → Column.integer (0 / 1)
 *  - TIMESTAMPTZ    → Column.text (ISO-8601 string)
 *  - UUID refs      → Column.text
 */
val AppSchema = Schema(
${tables.map(([table, columns]) => `    Table(
        name = "${table}",
        columns = listOf(
${columns.map((c) => {
  const line = `            Column.${c.type}("${c.name}"),`
  const comment = columnComment(c)
  return comment ? `${line.padEnd(53)} // ${comment}` : line
}).join('\n')}
        ),
    ),`).join('\n')}
)

/**
 * Table → columns stored locally as JSON text that are structured in Postgres
 * (JSONB, TEXT[], UUID[]). They must be parsed before upload: otherwise a JSONB
 * column stores a JSON *string*, and Postgres rejects an array column outright,
 * so PowerSync reverts the local write.
 */
val JSON_ENCODED_COLUMNS: Map<String, Set<String>> = mapOf(
${columnsWith('json').map(([table, names]) => `    "${table}" to setOf(${names.map((n) => `"${n}"`).join(', ')}),`).join('\n')}
)
`

const kotlinColors = `${header('//', 'tokens.json')}
package dev.brainfence.ui.theme

import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.Immutable
import androidx.compose.ui.graphics.Color

${['light', 'dark'].map((mode) => `internal val ${mode === 'light' ? 'Light' : 'Dark'}ColorScheme = ${mode}ColorScheme(
${colors.map(([role, c]) => `    ${role} = Color(0xFF${c[mode].slice(1)}),`).join('\n')}
)`).join('\n\n')}

/** Blocking-state colors, alongside the Material scheme. Read them with \`MaterialTheme.blockingColors\`. */
@Immutable
data class BlockingColors(
${blockingColors.map(([role]) => `    val ${role}: Color,`).join('\n')}
)

${['light', 'dark'].map((mode) => `internal val ${mode === 'light' ? 'Light' : 'Dark'}BlockingColors = BlockingColors(
${blockingColors.map(([role, c]) => `    ${role} = Color(0xFF${c[mode].slice(1)}),`).join('\n')}
)`).join('\n\n')}
`

// ── Windows ─────────────────────────────────────────────────────────────────

const tsSchema = `${header('//', 'schema.json')}
/** Every synced table and its local SQLite column types (\`id\` is implicit). */
export const TABLES = {
${tables.map(([table, columns]) => `  ${table}: {
${columns.map((c) => {
  const line = `    ${c.name}: '${c.type}',`
  const comment = columnComment(c)
  return comment ? `${line.padEnd(40)} // ${comment}` : line
}).join('\n')}
  },`).join('\n')}
} as const

/**
 * Table → columns stored locally as JSON text that are structured in Postgres
 * (JSONB, TEXT[], UUID[]). They must be parsed before upload: otherwise a JSONB
 * column stores a JSON *string*, and Postgres rejects an array column outright,
 * so PowerSync reverts the local write.
 */
export const JSON_COLUMNS: Record<string, readonly string[]> = {
${columnsWith('json').map(([table, names]) => `  ${table}: [${names.map((n) => `'${n}'`).join(', ')}],`).join('\n')}
}
`

const cssBlock = (mode, indent) =>
  [...colors, ...blockingColors].map(([role, c]) => `${indent}--${kebab(role)}: ${c[mode].toLowerCase()};`).join('\n') +
  `\n${indent}color-scheme: ${mode};`

const css = `${header('/*', 'tokens.json').replace(/\n\/\*/g, '\n *').replace(/\n$/, ' */\n')}
:root {
${cssBlock('light', '  ')}
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
${cssBlock('dark', '    ')}
  }
}
`

// The main process can't read CSS variables; it uses these for window backgrounds.
const tsColors = `${header('//', 'tokens.json')}
/** Every color role (Material 3, then blocking state) for each appearance. */
export const COLORS = {
${['light', 'dark'].map((mode) => `  ${mode}: {
${[...colors, ...blockingColors].map(([role, c]) => `    ${role}: '${c[mode]}',`).join('\n')}
  },`).join('\n')}
} as const
`

// ── macOS ───────────────────────────────────────────────────────────────────

const swiftSchema = `${header('//', 'schema.json')}
import PowerSync

/// PowerSync local SQLite schema — mirrors the Supabase Postgres tables.
///
/// - \`id\` is implicit (managed by PowerSync, never declared)
/// - JSONB / arrays → text (JSON), listed in \`SchemaColumns.json\`
/// - BOOLEAN → integer (0 / 1), listed in \`SchemaColumns.boolean\`
/// - TIMESTAMPTZ / UUID → text
let AppSchema = Schema(
${tables.map(([table, columns]) => `    Table(name: "${table}", columns: [
${columns.map((c) => {
  const line = `        .${c.type}("${c.name}"),`
  const comment = columnComment(c)
  return comment ? `${line.padEnd(43)} // ${comment}` : line
}).join('\n')}
    ]),`).join('\n').replace(/,$/, '')}
)
`

const swiftMap = (entries) =>
  entries.length === 0
    ? '[:]'
    : `[\n${entries.map(([table, names]) => `        "${table}": [${names.map((n) => `"${n}"`).join(', ')}],`).join('\n')}\n    ]`

const swiftColumns = `${header('//', 'schema.json')}
/// Columns whose local representation differs from Postgres, by table.
public enum SchemaColumns {
    /// JSONB and array columns (TEXT[] / UUID[]), stored locally as JSON text.
    /// Uploaded verbatim, a JSONB column would hold a JSON *string* and an array
    /// column is rejected (and the local write reverted), so they are parsed first.
    public static let json: [String: Set<String>] = ${swiftMap(columnsWith('json'))}

    /// BOOLEAN columns, stored locally as 0 / 1.
    public static let boolean: [String: Set<String>] = ${swiftMap(columnsWith('boolean'))}
}
`

const swiftPalette = `${header('//', 'tokens.json')}
import AppKit
import SwiftUI

/// Brainfence's Material 3 color roles, then its blocking-state roles, each
/// resolving to the light or dark value for the current appearance.
enum Palette {
${colors.map(([role, c]) => `    static let ${role} = Color(light: 0x${c.light.slice(1)}, dark: 0x${c.dark.slice(1)})`).join('\n')}

${blockingColors.map(([role, c]) => `    static let ${role} = Color(light: 0x${c.light.slice(1)}, dark: 0x${c.dark.slice(1)})`).join('\n')}
}

private extension Color {
    init(light: UInt32, dark: UInt32) {
        self.init(nsColor: NSColor(name: nil) { appearance in
            let hex = appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua ? dark : light
            return NSColor(
                srgbRed: CGFloat((hex >> 16) & 0xFF) / 255,
                green: CGFloat((hex >> 8) & 0xFF) / 255,
                blue: CGFloat(hex & 0xFF) / 255,
                alpha: 1
            )
        })
    }
}
`

// ── Write / check ───────────────────────────────────────────────────────────

const outputs = {
  'android/app/src/main/java/dev/brainfence/data/db/AppSchema.kt': kotlinSchema,
  'android/app/src/main/java/dev/brainfence/ui/theme/Color.kt': kotlinColors,
  'desktop-app/src/shared/schema.generated.ts': tsSchema,
  'desktop-app/src/renderer/src/tokens.css': css,
  'desktop-app/src/shared/tokens.generated.ts': tsColors,
  'macos/Brainfence/Sync/AppSchema.swift': swiftSchema,
  'macos/BrainfenceCore/Sources/BrainfenceCore/SchemaColumns.swift': swiftColumns,
  'macos/Brainfence/Theme/Palette.swift': swiftPalette,
}

let stale = 0
for (const [path, content] of Object.entries(outputs)) {
  const file = join(root, path)
  let current = null
  try {
    current = readFileSync(file, 'utf8').replace(/\r\n/g, '\n')
  } catch {}
  if (current === content) continue
  if (check) {
    console.error(`out of date: ${relative(process.cwd(), file)}`)
    stale++
  } else {
    mkdirSync(dirname(file), { recursive: true })
    writeFileSync(file, content)
    console.log(`wrote ${relative(process.cwd(), file)}`)
  }
}
if (stale) {
  console.error('Run `npm run codegen` and commit the result.')
  process.exit(1)
}
